#!/usr/bin/env python3
"""Check redirect hostnames and write a GitHub Actions DNS summary."""

from collections import Counter
from concurrent.futures import ThreadPoolExecutor
import os
from pathlib import Path
import re
import subprocess
import sys

ROOT = Path(__file__).resolve().parent.parent
RECORD_TYPES = ("CNAME", "A", "AAAA")


def hostnames(directory):
    hosts = set()
    for path in directory.glob("*.json"):
        hostname = path.name[:-5]
        hosts.add(hostname)
        # Match the aliases generated by make-caddy.py.
        if hostname.count(".") == 1:
            hosts.add(f"www.{hostname}")
    return sorted(hosts)


def lookup(hostname, record_type):
    try:
        result = subprocess.run(
            ["dig", "+time=3", "+tries=2", "+noall", "+comments", "+answer", hostname, record_type],
            capture_output=True, text=True, timeout=10, check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        return [], str(error)
    status = re.search(r"status: (\w+)", result.stdout)
    if result.returncode or not status:
        return [], result.stderr.strip() or "DNS lookup failed"
    if status.group(1) not in ("NOERROR", "NXDOMAIN"):
        return [], f"DNS status {status.group(1)}"
    records = []
    for line in result.stdout.splitlines():
        fields = line.split()
        if (len(fields) >= 5 and fields[3] == record_type
                and (record_type != "NS" or fields[0].rstrip(".").lower() == hostname.rstrip(".").lower())):
            records.append(fields[4].rstrip("."))
    return sorted(set(records)), None


def lookup_nameservers(hostname):
    # NS records belong to a zone, which may be a parent of the hostname.
    # Ignore NS answers for CNAME targets: they govern a different zone.
    labels = hostname.rstrip(".").split(".")
    for index in range(len(labels)):
        zone = ".".join(labels[index:])
        nameservers, error = lookup(zone, "NS")
        if error:
            return [], f"NS ({zone}): {error}"
        if nameservers:
            return nameservers, None
    return [], "NS: no authoritative nameservers found"


def check_host(hostname):
    records, errors = {}, []
    for record_type in RECORD_TYPES:
        records[record_type], error = lookup(hostname, record_type)
        if error:
            errors.append(f"{record_type}: {error}")
    records["NS"], error = lookup_nameservers(hostname)
    if error:
        errors.append(error)
    return hostname, records, errors


def code(value):
    # Hostnames and resolver errors are external input; keep them inside the cell.
    return "`" + str(value).replace("`", "'").replace("|", "\\|").replace("\n", " ") + "`"


def domain_link(value):
    # Keep DNS names in ASCII in the URL while displaying internationalized labels.
    try:
        display = value.encode("ascii").decode("idna")
    except (UnicodeError, ValueError):
        display = value
    if not re.fullmatch(r"[A-Za-z0-9.-]+", value):
        return code(display)
    return f"[{code(display)}](https://{value})"


def report(results):
    # Compare complete record sets, counting each hostname once per type.
    # Empty record sets do not participate in comparisons.
    common = {}
    for kind in ("A", "AAAA"):
        counts = Counter(tuple(sorted(set(records[kind]))) for _, records, failures in results
                         if records[kind] and not failures)
        highest = max(counts.values(), default=0)
        common[kind] = {value for value, count in counts.items() if count == highest}

    errors = []
    failed_count = 0
    rows = {"failed": [], "warning": [], "ok": []}
    for hostname, records, failures in results:
        deviations = []
        for kind in ("A", "AAAA"):
            value = tuple(sorted(set(records[kind])))
            if value and common[kind] and value not in common[kind]:
                deviations.append(kind)
        if not any(records[kind] for kind in RECORD_TYPES):
            deviations.append("no records")
        if failures:
            errors.append((hostname, "; ".join(failures)))
        failed = bool(deviations or failures)
        failed_count += failed
        warning = hostname.count(".") > 1 and not records["CNAME"] and not failed
        category = "failed" if failed else "warning" if warning else "ok"
        status = "❌ Failed" if failed else "🟠 Warning (missing CNAME)" if warning else "✅ OK"
        if deviations:
            status += " (" + ", ".join(deviations) + ")"
        values = [", ".join(domain_link(value) if kind in ("CNAME", "NS") else code(value)
                            for value in records[kind]) or "-"
                  for kind in ("CNAME", "AAAA", "A", "NS")]
        rows[category].append(f"| {status} | {domain_link(hostname)} | {' | '.join(values)} |")
    lines = ["# DNS report", ""]
    for category, title in (("failed", "Failed domains"), ("warning", "Warnings"), ("ok", "OK domains")):
        lines += [f"## {title} ({len(rows[category])})", "", "| Status | Hostname | CNAME | AAAA | A record | NS record |", "| --- | --- | --- | --- | --- | --- |"]
        lines += rows[category] or ["| — | — | — | — | — | — |"]
        lines.append("")
    lines += ["", f"Checked **{len(results)}** hostnames; **{failed_count}** failed.", "", "A and AAAA records are compared separately with their most common complete record set, only when present. CNAME hosts are classified by their resolved addresses; CNAME targets are not compared. Tied most-common sets are accepted. Hostnames with no records or lookup errors fail. Subdomains without a CNAME are warnings.", ""]
    if errors:
        lines += ["## Lookup errors", "", "| Hostname | Error |", "| --- | --- |"]
        lines += [f"| {domain_link(host)} | {code(error)} |" for host, error in errors]
        lines.append("")
    return "\n".join(lines), bool(failed_count)


def main():
    hosts = hostnames(ROOT / "domains")
    if not hosts:
        print("No domain JSON files found", file=sys.stderr)
        return 1
    with ThreadPoolExecutor(max_workers=20) as executor:
        results = list(executor.map(check_host, hosts))
    summary, failed = report(results)
    print(summary)
    if os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(os.environ["GITHUB_STEP_SUMMARY"], "a", encoding="utf-8") as output:
            output.write(summary + "\n")
    return int(failed)


if __name__ == "__main__":
    sys.exit(main())
